  {
    category: "Electronics"
  },
  {
    _id: 0,
    category: 1,
    name: 1,
    price: 1
  }
)
```

Changing an indexed field requires updating its index entries:

```javascript
db.products.updateOne(
  {
    sku: "ELEC-3000"
  },
  {
    $set: {
      category: "Computer Accessories"
    }
  }
)
```

